static void agent_main_loop ( struct agent_info * s ) { int cpu ; pthread_t rw_thread_per_cpu [ MAX_CPUS ] ; for ( cpu = 0 ; cpu < s -> cpus ; cpu ++ ) { rw_thread_per_cpu [ cpu ] = rw_thread_run ( s -> rw_ti [ cpu ] ) ; } rw_ctl_loop ( s -> ctl_fd , NULL ) ; for ( cpu = 0 ; cpu < s -> cpus ; cpu ++ ) { int ret ; ret = pthread_join ( rw_thread_per_cpu [ cpu ] , NULL ) ; if ( ret != 0 ) { pr_err ( "pthread_join() error:%d (cpu %d)\n" , ret , cpu ) ; exit ( EXIT_FAILURE ) ; } } } 